/* cqw is relative to this scroll-free calendar container. With twelve
   equal-width month tracks, the cells and their gaps shrink together to
   fit the full year on any viewport, never wrapping into multiple rows. */
.community-page #profileContent .profile-calendar-section .month-calendar-scroll{
  container-type:inline-size;
  overflow-x:hidden!important;
  overscroll-behavior-inline:contain;
  padding:0 0 7px!important;
  scrollbar-width:none;
}
.community-page #profileContent .profile-calendar-section .month-calendar{
  --calendar-month-gap:clamp(2px,.62cqw,9px);
  --calendar-day-gap:clamp(1px,.2cqw,3px);
