 const step=Math.max(1,Math.ceil(peak/4));
 const ticks=Math.max(1,Math.ceil(peak/step));
 return {max:step*ticks,step,ticks};
}
export function straightPath(points){
 if(!points.length)return '';
 const f=n=>Number(n.toFixed(2));
